UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/CostaBrava.unity", UnityEditor.SceneManagement.OpenSceneMode.Single);
var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
for (int i = 0; i < garage.variants.Length; i++)
{
    if (garage.specIds[i] != "ferrari458") continue;
    var v = garage.variants[i];
    sb.AppendLine("variant " + v.root.name + " active=" + v.root.activeSelf);
    foreach (Transform t in v.root.GetComponentsInChildren<Transform>())
    {
        var r = t.GetComponent<Renderer>();
        if (r == null) continue;
        Vector3 worldSize = r.bounds.size;
        if (worldSize.x > 3.2f || worldSize.y > 2.2f || worldSize.z > 3.2f)
        {
            sb.AppendLine("  OVERSIZED " + t.name + " worldSize=" + worldSize.ToString("F2") + " localScale=" + t.localScale.ToString("F3") + " localRot=" + t.localRotation.eulerAngles.ToString("F1"));
        }
    }
    break;
}
Debug.Log("PROBE11 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
